import type { DomSnapshot } from "../../types/dom-automation.js";
import { locateOrStatus } from "./amazon-invoice-upload-flow-support.js";
import type { AmazonInvoiceUploadMissionInput } from "./mission.schema.js";

const EXISTING_INVOICE_HINTS = [
  "invoice uploaded successfully",
  "Thank you for uploading the file",
  "Thank you for uploading the document",
  "The customer can download the file directly from their account",
  "The customer will be able to download it directly from their account",
  "Generated by seller",
  "Seller generated",
  "感谢您上传文件",
  "客户可以直接从自己的账户下载文件",
  "由卖家生成",
  "成功：已上传",
  "已上传",
];

const UPLOAD_READY_ACTION_HINTS = [
  "Upload another invoice or credit note",
  "上传其他发票或贷记单",
];

const INVOICE_TABLE_HEADER_GROUPS = [
  ["日期", "类型", "编号", "状态", "操作"],
  ["date", "type", "number", "status", "action"],
] as const;

const INVOICE_FAILURE_HINTS = [
  "failed",
  "invalid",
  "error",
  "read failed",
  "no available actions",
  "文件上传失败",
  "无法上传",
  "编号无效",
  "读取失败",
  "很抱歉，目前没有可用的操作",
] as const;

const INVOICE_ROW_CONTEXT_HINTS = [
  "invoice",
  "credit note",
  "seller generated",
  "generated by seller",
  "waiting",
  "pending",
  "uploaded",
  "发票",
  "贷记单",
  "由卖家生成",
  "等待中",
  "待处理",
  "已上传",
] as const;

export type ExistingInvoiceConfirmation =
  | { status: "confirmed"; reason: string }
  | { status: "rejected"; reason: string }
  | { status: "pending"; reason: string };

export function locateManageInvoiceEntry(snapshot: DomSnapshot): ReturnType<typeof locateOrStatus> {
  const zhEntry = locateOrStatus({
    snapshot,
    targetKind: "button",
    hints: ["管理发票"],
    requiredText: "管理发票",
    notFoundStatus: "upload_entry_not_found",
  });
  if (zhEntry.ok) return zhEntry;
  return locateOrStatus({
    snapshot,
    targetKind: "button",
    hints: ["manage invoice"],
    requiredText: "manage invoice",
    notFoundStatus: "upload_entry_not_found",
  });
}

export function hasExistingInvoiceEvidence(
  snapshot: DomSnapshot,
  mission: AmazonInvoiceUploadMissionInput,
): boolean {
  return observeExistingInvoiceConfirmation(snapshot, mission).status === "confirmed";
}

export function observeExistingInvoiceConfirmation(
  snapshot: DomSnapshot,
  mission: AmazonInvoiceUploadMissionInput,
): ExistingInvoiceConfirmation {
  const dialogTexts = currentOrderDialogTexts(snapshot, mission);
  if (dialogTexts.length === 0) {
    return { status: "pending", reason: "No current-order invoice dialog is visible yet." };
  }
  if (dialogTexts.length !== 1) {
    return { status: "rejected", reason: "Expected exactly one current-order invoice dialog." };
  }
  const dialogText = dialogTexts[0] ?? "";
  if (hasFailureState(dialogText)) {
    return { status: "rejected", reason: "The unique current-order invoice dialog exposes a governed failure state." };
  }
  const invoiceRows = snapshot.tableRows.length > 0 ? snapshot.tableRows : snapshot.roleRows;
  const matchingRows = invoiceRows
    .map((row) => normalizeText(row.visibleText ?? ""))
    .filter((text) => hasExpectedInvoiceId(text, mission) && hasInvoiceRowContext(text));
  if (matchingRows.some(hasFailureState)) {
    return { status: "rejected", reason: "The expected invoice row exposes a governed failure state." };
  }
  const uploadedRows = matchingRows.filter(hasKnownInvoiceState);
  const dialogCarriesAcceptedReceipt = hasKnownInvoiceState(dialogText);
  if (matchingRows.length === 1 && (uploadedRows.length === 1 || dialogCarriesAcceptedReceipt)) {
    return {
      status: "confirmed",
      reason: "Confirmed one current-order invoice dialog and one expected invoice row in uploaded state, with no duplicate or failure state.",
    };
  }
  if (matchingRows.length > 1 || uploadedRows.length > 1) {
    return { status: "rejected", reason: "Expected invoice identity is duplicated in the current-order invoice result." };
  }
  return { status: "pending", reason: "Current-order invoice dialog has not exposed one unique expected uploaded row yet." };
}

export function findOrderBoundInvoiceDialogText(
  snapshot: DomSnapshot,
  mission: AmazonInvoiceUploadMissionInput,
): string | null {
  const dialogTexts = currentOrderDialogTexts(snapshot, mission);
  return dialogTexts.length === 1 ? dialogTexts[0] ?? null : null;
}

export function hasInvoiceDialogReadyForUpload(
  snapshot: DomSnapshot,
  mission: AmazonInvoiceUploadMissionInput,
): boolean {
  if (hasExistingInvoiceEvidence(snapshot, mission)) return false;
  return currentOrderDialogTexts(snapshot, mission).some((text) =>
    UPLOAD_READY_ACTION_HINTS.some((hint) => text.includes(normalizeText(hint)))
      && INVOICE_TABLE_HEADER_GROUPS.some((headers) => headers.every((header) => text.includes(normalizeText(header)))));
}

function currentOrderDialogTexts(
  snapshot: DomSnapshot,
  mission: AmazonInvoiceUploadMissionInput,
): string[] {
  const orderId = normalizeText(mission.amazonOrderId);
  const titleHints = [
    `订单${orderId}的发票`,
    `invoice for order ${orderId}`,
    `invoices for order ${orderId}`,
    `order ${orderId} invoice`,
  ];
  return snapshot.dialogs
    .map((dialog) => normalizeText(`${dialog.visibleText ?? ""} ${dialog.ariaLabel ?? ""}`))
    .filter((text) => titleHints.some((hint) => text.includes(hint)));
}

function hasExpectedInvoiceId(
  text: string,
  mission: AmazonInvoiceUploadMissionInput,
): boolean {
  const normalizedIds = [mission.invoiceNo, mission.amazonOrderId].map(normalizeText);
  return normalizedIds.some((value) => text.includes(value));
}

function hasKnownInvoiceState(text: string): boolean {
  return EXISTING_INVOICE_HINTS.some((hint) => text.includes(normalizeText(hint)));
}

function hasFailureState(text: string): boolean {
  return INVOICE_FAILURE_HINTS.some((hint) => text.includes(normalizeText(hint)));
}

function hasInvoiceRowContext(text: string): boolean {
  return INVOICE_ROW_CONTEXT_HINTS.some((hint) => text.includes(normalizeText(hint))) || hasFailureState(text);
}

function normalizeText(value: string): string {
  return value.toLowerCase().replace(/\s+/g, " ").trim();
}
